def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    aggressive_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0.0)
            prev_bids.append(bid)
            if bid >= DAILY_SALARY * 1.5:
                aggressive_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    cindy_like_pressure = len(aggressive_bids) >= 1

    remaining_days = max(1, 10 - day + 1)
    reserve_target = DAILY_SALARY * 0.45 * remaining_days
    spendable = max(0.0, budget - reserve_target)

    if hp <= 2 or no_water_days >= 2:
        if cindy_like_pressure:
            bid = min(budget, max(DAILY_SALARY * 1.65, highest_prev * 0.92))
        else:
            bid = min(budget, max(DAILY_SALARY * 0.95, highest_prev + 3.0))
        return float(max(0.0, bid))

    if hp <= 4 or no_water_days >= 1:
        if cindy_like_pressure:
            bid = max(DAILY_SALARY * 1.2, min(budget, highest_prev * 0.82))
        else:
            bid = max(DAILY_SALARY * 0.7, highest_prev + 2.0)
        bid = min(budget, bid)
        return float(max(0.0, bid))

    if supply >= 22:
        base = DAILY_SALARY * 0.18
    elif supply >= 19:
        base = DAILY_SALARY * 0.28
    else:
        base = DAILY_SALARY * 0.4

    if cindy_like_pressure:
        base *= 0.75

    if spendable > 0:
        bid = min(budget, max(base, min(spendable * 0.35, DAILY_SALARY * 0.6)))
    else:
        bid = min(budget, base)

    if avg_prev > 0 and avg_prev < DAILY_SALARY:
        bid = max(bid, min(budget, avg_prev + 1.5))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((oid, opp))

    # If no opponents alive, bid to survive comfortably
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    yesterday_bids = []
    for oid, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline: target a mid allocation pressure
    # If supply is high, we can bid less; if low, bid more.
    supply_ratio = 0.0
    try:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        supply_ratio = 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Conservative base bid to avoid overpaying
    base_bid = DAILY_SALARY * (0.65 - 0.25 * supply_ratio)

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If I'm in danger, bid aggressively regardless
    if my_hp <= 2 or no_water_days >= 2:
        bid = DAILY_SALARY * 0.95
        return float(min(my_budget, bid))

    # React to yesterday's highest bid (likely indicates who is fighting for water)
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Cindy-like consistent bidder likely has relatively high yesterday bids and survived.
        # If someone bid very high yesterday, slightly increase to compete.
        if highest_prev_bid >= DAILY_SALARY * 1.6:
            bid = base_bid + DAILY_SALARY * 0.25
        elif highest_prev_bid >= DAILY_SALARY * 1.2:
            bid = base_bid + DAILY_SALARY * 0.12
        else:
            bid = base_bid
    else:
        bid = base_bid

    # Ensure bid is at least enough to have a chance but not too wasteful
    bid = max(DAILY_SALARY * 0.45, bid)
    bid = min(bid, DAILY_SALARY * 0.9)

    return float(min(my_budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]

    supply = day_context['supply']
    num_players = len(alive_opponents) + 1

    # Calculate threshold for winning based on supply distribution
    fair_share = supply / num_players

    # If supply is tight, bid aggressively
    if fair_share < WATER_REQ:
        base_bid = DAILY_SALARY * 0.9
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust based on Cindy's high historical bidding
    cindy = opponents_status.get('Cindy', {})
    if cindy.get('alive', False):
        prev_cindy = cindy.get('previous_trace', {})
        if prev_cindy and prev_cindy.get('bid', 0) > base_bid:
            base_bid = min(my_status['budget'], prev_cindy['bid'] + 2.0)

    # Ensure we don't exceed budget or spend unnecessarily if HP is high
    if my_status['hp'] > 8:
        base_bid *= 0.7

    return float(min(my_status['budget'], max(0, base_bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    supply = day_context['supply']
    # base bid
    if my_status['hp'] <= 2:
        base = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 4:
        base = DAILY_SALARY * 0.7
    else:
        base = DAILY_SALARY * 0.5

    # adjust based on yesterday's highest
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If they were very aggressive, lower to save budget
        if highest_prev >= DAILY_SALARY * 0.85:
            base = min(base, DAILY_SALARY * 0.3)
        else:
            # try to beat their average? but we'll bid just above highest_prev + small increment
            challenger = min(DAILY_SALARY * 0.95, highest_prev + 1.5)
            base = max(base, challenger)

    # Supply: if low supply, increase bid
    if supply < (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        base *= 1.2
    else:
        base *= 0.9

    # Cap by budget and max reasonable
    bid = min(my_status['budget'], base)
    bid = min(bid, DAILY_SALARY * 0.95)
    bid = max(bid, 1)
    return int(round(bid))
